public class Proprietaire {
    //ATTRIBUTS
    private String nom;
    private String prenom;
    private Voiture voiture;
    private int pointsPermis = 12;

    //CONSTRUCTEUR
    public Proprietaire(String nom, String prenom, Voiture voiture) {
        this.nom = nom;
        this.prenom = prenom;
        this.voiture = voiture;
    }

    //METHODES
    public int commettreInfraction(String infraction){
        if(infraction == "exces"){
            pointsPermis = pointsPermis-1;
        }else if(infraction == "telephone"){
            pointsPermis = pointsPermis-2;
        }else if(infraction == "feu"){
            pointsPermis = pointsPermis-3;
        }
        return pointsPermis;
    }

    public int realiserStage(){
        if(pointsPermis < 10){
            pointsPermis = pointsPermis+2;
        }else if(pointsPermis > 10){
            pointsPermis = 12;
        }
        return pointsPermis;
    }

    //METHODE TOSTRING()
    @Override
    public String toString() {
        return nom + " " + prenom + " dispose de " + pointsPermis + " points sur son permis de conduire.";
    }

    //GETTERS/SETTERS
    public String getNom() {
        return nom;
    }

    public String getPrenom() {
        return prenom;
    }

    public Voiture getVoiture() {
        return voiture;
    }

    public int getPointsPermis() {
        return pointsPermis;
    }

    public void setNom(String nom) {
        this.nom = nom;
    }

    public void setPrenom(String prenom) {
        this.prenom = prenom;
    }

    public void setVoiture(Voiture voiture) {
        this.voiture = voiture;
    }

    public void setPointsPermis(int pointsPermis) {
        this.pointsPermis = pointsPermis;
    }

}

